    if [[ "$argc__parts_len" -le 1 ]]; then
        _choice_signal | _argc_util_transform suffix=: nospace
    else
        _choice_signal
    fi
}

_choice_notify() {
    printf '%s\n' both start end
}

_choice_on_busy_update() {
    printf '%s\n' queue do-nothing restart signal
}

_choice_shell() {
    printf '%s\n' none
    local shell
    local -a shells=()
    if [[ -f /etc/shells ]]; then
        while IFS= read -r shell; do
            [[ -z $shell || $shell == '#'* ]] && continue
            shells+=("${shell##*/}")
        done </etc/shells
    fi
    if ((${#shells[@]} == 0)); then
        shells=(bash zsh fish sh)
    fi
    printf '%s\n' "${shells[@]}" | gawk '!seen[$0]++'
}

_choice_signal() {
    command kill -l 2>/dev/null | gawk '{
        for (i = 1; i <= NF; i++) {
            if ($i ~ /^SIG[A-Z][A-Z0-9]*$/) print $i
            else if ($i ~ /^[A-Z][A-Z0-9]*$/) print "SIG" $i
        }
    }'
}

_choice_wrap_process() {
